export type WhatsAppEnvSnapshot = {
  waJsVersion: string | null;
  waVersion: string | null;
  windowsBuild: string | null;
  isBusinessAccount: boolean | null;
};

type WhatsAppEnvResponse =
  | { ok: true; snapshot: WhatsAppEnvSnapshot }
  | { ok: false; error?: string };

const WHATSAPP_URL_PATTERN = "https://web.whatsapp.com/*";

async function getWhatsAppTabId(): Promise<number | null> {
  try {
    const tabs = await chrome.tabs.query({ url: WHATSAPP_URL_PATTERN });
    const tab = tabs?.[0];
    return typeof tab?.id === "number" ? tab.id : null;
  } catch {
    return null;
  }
}

export async function collectWhatsAppEnvSnapshot(): Promise<WhatsAppEnvSnapshot | null> {
  const tabId = await getWhatsAppTabId();
  if (!tabId) return null;

  // Preferred path: reuse existing content scripts (no new manifest permissions).
  try {
    const response = await Promise.race([
      chrome.tabs.sendMessage(tabId, {
        action: "telemetry.getWhatsappEnv",
      }) as Promise<WhatsAppEnvResponse>,
      new Promise<WhatsAppEnvResponse>((resolve) =>
        setTimeout(() => resolve({ ok: false, error: "timeout" }), 2500)
      ),
    ]);

    if (response && (response as WhatsAppEnvResponse).ok) {
      return (response as { ok: true; snapshot: WhatsAppEnvSnapshot }).snapshot;
    }
  } catch {
    // ignore and try fallback
  }

  // Fallback: try chrome.scripting.executeScript if available/allowed.
  const scripting = chrome.scripting;
  if (!scripting?.executeScript) return null;

  try {
    const results = await scripting.executeScript({
      target: { tabId },
      // Need MAIN world to read window.WPP (page context).
      world: "MAIN",
      func: async () => {
        const WPP = (window as any)?.WPP;

        const snapshot: {
          waJsVersion: string | null;
          waVersion: string | null;
          windowsBuild: string | null;
          isBusinessAccount: boolean | null;
        } = {
          waJsVersion: null,
          waVersion: null,
          windowsBuild: null,
          isBusinessAccount: null,
        };

        if (!WPP) return snapshot;

        if (typeof WPP.version === "string") {
          snapshot.waJsVersion = WPP.version;
        }

        try {
          const constants = await WPP.conn?.getBuildConstants?.();
          if (constants && typeof constants === "object") {
            const versionStr = (constants as any).VERSION_STR;
            const windowsBuild = (constants as any).WINDOWS_BUILD;
            if (typeof versionStr === "string") snapshot.waVersion = versionStr;
            if (typeof windowsBuild === "string")
              snapshot.windowsBuild = windowsBuild;
          }
        } catch {
          // ignore
        }

        try {
          const myId = WPP.conn?.getMyUserId?.();
          const me = myId ? await WPP.contact?.get?.(myId) : undefined;
          snapshot.isBusinessAccount =
            !!me?.isBusiness || !!me?.isEnterprise || !!me?.isVerifiedBusiness;
        } catch {
          // ignore
        }

        return snapshot;
      },
    });

    const result = results?.[0]?.result as WhatsAppEnvSnapshot | undefined;
    return result ?? null;
  } catch {
    return null;
  }
}
