let sessionWriteQueue: Promise<void> = Promise.resolve();

async function finalizeAndPersistSession(
  partial: Partial<Session>,
  source: string,
): Promise<Session> {
  sessionWriteQueue = sessionWriteQueue
    .then(async () => {
      const beforePermissions = session.permissions || [];
      let current: Session = { ...session };

      if (!current.logged && !current.email) {
        try {
          const cached = await chrome.storage.local.get("cachedSession");
          if (cached.cachedSession) {
            current = { ...current, ...cached.cachedSession };
          }
        } catch {
          // ignore cache load errors
        }
      }

      const merged: Session = {
        logged: partial.logged ?? current.logged ?? false,
        lastRefresh: partial.lastRefresh ?? current.lastRefresh,
        email: partial.email ?? current.email,
        role: partial.role ?? current.role,
        permissions: partial.permissions ?? current.permissions ?? [],
        // Para alguns campos, precisamos permitir "limpar" valores antigos.
        // Usar `in` permite sobrescrever mesmo quando o valor é `undefined`.
        hasPlan: "hasPlan" in partial ? partial.hasPlan : current.hasPlan,
        trialStatus:
          "trialStatus" in partial ? partial.trialStatus : current.trialStatus,
        trialEndsAt:
          "trialEndsAt" in partial ? partial.trialEndsAt : current.trialEndsAt,
        statusReview:
          "statusReview" in partial
            ? partial.statusReview
            : current.statusReview,
        scoreReview:
          "scoreReview" in partial ? partial.scoreReview : current.scoreReview,
        msgReview:
          "msgReview" in partial ? partial.msgReview : current.msgReview,
      };

      const featureMap = (
        Array.isArray(merged.permissions) ? merged.permissions : []
      ).reduce<Record<string, boolean>>((acc, permission) => {
        if (permission) acc[permission] = true;
        return acc;
      }, {});

      let effectiveFeatures = featureMap;

      const debugInfo = getDevBypassDebugInfo();

      if (DEV_BYPASS_ENABLED && merged.email) {
        if (debugInfo.enabled) {
          console.log(
            "[DEV_BYPASS] enabled=%s hasHash=%s",
            debugInfo.enabled,
            debugInfo.hasEmailHash,
          );
        }

        const allowed = await isDevBypassAllowed(merged.email);
        if (debugInfo.enabled) {
          if (DEV_BYPASS_ENABLED) {
            console.log("[DEV_BYPASS] allowed=%s", allowed);
          }
        }

        if (allowed) {
          effectiveFeatures = applyDevBypass(featureMap);
        }
      } else if (debugInfo.enabled) {
        console.log(
          "[DEV_BYPASS] enabled but skipped (email missing=%s)",
          !merged.email,
        );
      } else {
        if (DEV_BYPASS_ENABLED) {
          console.log(
            "[DEV_BYPASS] disabled (DEV=%s hasHash=%s)",
            debugInfo.enabled,
            debugInfo.hasEmailHash,
          );
        }
      }

      const permissionsAfter = Object.keys(effectiveFeatures).filter(
        (key) => effectiveFeatures[key],
      );

      merged.permissions = permissionsAfter;

      if (DEV_BYPASS_ENABLED) {
        console.log(
          "[SESSION_WRITE] source=%s permissionsBefore=%o permissionsAfter=%o",
          source,
          beforePermissions,
          permissionsAfter,
        );
      }

      session = {
        ...session,
        ...merged,
      };

      const cachedSession = {
        logged: session.logged,
        email: session.email,
        role: session.role,
        permissions: session.permissions,
        hasPlan: session.hasPlan,
        trialStatus: session.trialStatus,
        trialEndsAt: session.trialEndsAt,
        statusReview: session.statusReview,
        scoreReview: session.scoreReview,
        msgReview: session.msgReview,
      };

      if (session.logged) {
        await chrome.storage.local.set({ cachedSession });
      } else {
        await chrome.storage.local.remove("cachedSession");
      }

      const tab = await getTab();
      if (tab?.id) {
        chrome.tabs.sendMessage(tab.id, {
          action: "session.updated",
          data: cachedSession,
        });
      }
    })
    .catch((error) => {
      console.error("[SESSION_WRITE] failed:", error);
    });

  await sessionWriteQueue;
  return session;
}

