/**
 * Busca a versão publicada via API própria do RevZap.
 * Endpoint esperado: GET /extension/version → { "version": "X.Y.Z" }
 * Usar a API própria é mais confiável que o endpoint clients2.google.com,
 * que retorna "noupdate" para extensões não listadas publicamente na loja.
 * Roda no background para ter acesso ao apiUrl e evitar CORS no content script.
 */
function handleFetchStoreVersion(
  sendResponse: (response: { version: string | null; sw: boolean }) => void,
): void {
  if (!apiUrl) {
    sendResponse({ version: null, sw: false });
    return;
  }

  fetch(`${apiUrl}/extension/version`, { cache: "no-store" })
    .then((res) => {
      if (!res.ok) return sendResponse({ version: null, sw: false });
      return res.json();
    })
    .then((data: { version?: string; sw?: string | boolean } | void) => {
      const version = data?.version ?? null;
      // Aceita sw como string "true"/"false" ou booleano direto
      const sw = data?.sw === true || data?.sw === "true";
      sendResponse({ version, sw });
    })
    .catch(() => sendResponse({ version: null, sw: false }));
}

