// Nova lógica do maturador usando o pipeline do disparador
async function handleMaturadorStartShoot(sendResponse: SendResponse) {
  try {
    const shoot = await criarShootMaturador();

    if (!shoot) {
      return sendResponse({
        ok: false,
        error: "Erro ao criar shoot do maturador",
      });
    }

    sendResponse({ ok: true, shootId: shoot.id });

    // Dispara o shoot automaticamente
    setTimeout(() => {
      dispararShootMaturador(shoot.id!);
    }, 1000);
  } catch (error) {
    sendResponse({
      ok: false,
      error: (error as Error).message || "Erro ao criar shoot",
    });
  }
}

async function criarShootMaturador() {
  try {
    const res = await chrome.storage.local.get("accessToken");
    const accessToken = res.accessToken;

    if (!accessToken) {
      return null;
    }

    // Busca dados do maturador no backend
    const maturadorResponse = await fetch(`${apiUrl}/maturador`, {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
    });

    const maturadorResult = await maturadorResponse.json();

    if (
      !maturadorResponse.ok ||
      !maturadorResult.ok ||
      !maturadorResult.temPermissao
    ) {
      return null;
    }

    const numeroAtivo = maturadorResult.maturador?.find(
      (item: any) => item.ligado === true,
    );

    if (!numeroAtivo?.whatsapp) {
      return null;
    }

    // Busca lista global de contatos
    const globalResponse = await fetch(`${apiUrl}/maturador/global`, {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
    });

    const globalResult = await globalResponse.json();

    if (
      !globalResponse.ok ||
      !globalResult.numeros ||
      !Array.isArray(globalResult.numeros)
    ) {
      return null;
    }

    const numeroAtualNormalizado = normalizarWhatsapp(numeroAtivo.whatsapp);

    // Filtra contatos elegíveis (não inclui o próprio usuário e só ligados)
    const contatos = globalResult.numeros
      .filter((n: any) => {
        const normalizado = normalizarWhatsapp(n.whatsapp);
        return normalizado !== numeroAtualNormalizado && n.ligado === true;
      })
      .map((n: any) => {
        const cleanChatId = n.whatsapp.replace(/@(lid|c\.us|g\.us)$/g, "");
        let server = "@c.us";

        if (n.whatsapp.includes("@g.us")) {
          server = "@g.us";
        } else if (n.whatsapp.includes("@lid")) {
          server = "@lid";
        }

        return {
          chatId: cleanChatId,
          userId: cleanChatId,
          server: server,
          sent: false, // Importante: marca como não enviado
          error: false,
          source: {
            type: "spreadsheet" as const, // Usa "spreadsheet" para compatibilidade
            ids: [],
          },
        };
      });

    if (contatos.length === 0) {
      return null;
    }

    // Embaralha aleatoriamente a lista de contatos (Fisher-Yates shuffle)
    // Isso garante que contatos mais recentes também recebam mensagens
    for (let i = contatos.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [contatos[i], contatos[j]] = [contatos[j], contatos[i]];
    }

    // Remove shoot antigo do maturador se existir
    const tab = await getTab();
    if (!tab?.id) {
      return null;
    }
    try {
      const response = await chrome.tabs.sendMessage(tab.id, {
        action: "maturador.getShoots",
      });

      if (response?.ok && response.shoots) {
        const maturadorShoot = response.shoots.find(
          (s: any) => s.hidden === true,
        );
        if (maturadorShoot?.id) {
          await chrome.tabs.sendMessage(tab.id, {
            action: "maturador.deleteShoot",
            data: { id: maturadorShoot.id },
          });
        }
      }
    } catch (error) {
      // Continua mesmo se falhar
    }

    // Cria novo shoot com as mensagens do maturador como itens
    const shootData = {
      title: "🤖 Maturador Automático",
      contacts: contatos,
      interval: [
        (numeroAtivo.delayMin || 1) * 60, // Converte minutos para segundos
        (numeroAtivo.delayMax || 2) * 60,
      ],
      items: [], // Será preenchido com mensagens de texto
      status: undefined,
      hidden: true, // Marca como oculto
      randomizeActions: false,
    };

    // Cria o shoot no Dexie via mensagem
    const result = await chrome.tabs.sendMessage(tab.id, {
      action: "maturador.createShoot",
      data: shootData,
    });

    if (!result?.ok || !result.shoot) {
      return null;
    }

    return result.shoot;
  } catch (error) {
    return null;
  }
}

async function dispararShootMaturador(shootId: number) {
  try {
    const tab = await getTab();
    if (!tab?.id) {
      return;
    }

    // Dispara o shoot via mensagem
    await chrome.tabs.sendMessage(tab.id, {
      action: "maturador.startShooting",
      data: { shootId },
    });
  } catch (error) {
    // Ignora erros silenciosamente
  }
}

// Listener para quando o shoot do maturador termina
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === "maturador.shootFinished") {
    // Aguarda um pouco antes de reiniciar
    setTimeout(async () => {
      try {
        const res = await chrome.storage.local.get("maturadorStatus");
        const status = res.maturadorStatus;

        // Só reinicia se o maturador ainda estiver ativo
        if (status?.ativo) {
          // Tenta criar e disparar novo shoot
          // Se falhar, tenta novamente após um tempo
          try {
            await handleMaturadorStartShoot(() => {});
          } catch (error) {
            // Se falhar, tenta novamente após 10 segundos
            setTimeout(async () => {
              const res2 = await chrome.storage.local.get("maturadorStatus");
              if (res2.maturadorStatus?.ativo) {
                handleMaturadorStartShoot(() => {}).catch(() => {
                  // Se falhar novamente, tenta mais uma vez após 30 segundos
                  setTimeout(async () => {
                    const res3 =
                      await chrome.storage.local.get("maturadorStatus");
                    if (res3.maturadorStatus?.ativo) {
                      handleMaturadorStartShoot(() => {});
                    }
                  }, 30000);
                });
              }
            }, 10000);
          }
        }
      } catch (error) {
        // Em caso de erro, tenta novamente após 15 segundos
        setTimeout(async () => {
          const res = await chrome.storage.local.get("maturadorStatus");
          if (res.maturadorStatus?.ativo) {
            handleMaturadorStartShoot(() => {});
          }
        }, 15000);
      }
    }, 3000); // Aguarda 3 segundos antes de reiniciar

    sendResponse({ ok: true });
    return true;
  }

  return false;
});

async function handleShootingReportContacts(
  data: { contacts: any[] },
  sendResponse: SendResponse,
) {
  // Responde imediatamente (fire-and-forget) para não bloquear o disparo
  sendResponse({ ok: true });

  try {
    const res = await chrome.storage.local.get("accessToken");
    const accessToken = res.accessToken;

    if (!accessToken || !data?.contacts?.length) return;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    await fetch(`${apiUrl}/shooting/contacts`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
      body: JSON.stringify({
        contacts: data.contacts,
      }),
      signal: controller.signal,
    });

    clearTimeout(timeout);
  } catch {
    // Silencioso: falha no report não deve impactar o disparo
  }
}

async function handleReviewSubmit(
  data: { score: number; message: string },
  sendResponse: SendResponse,
) {
  try {
    const res = await chrome.storage.local.get("accessToken");
    const accessToken = res.accessToken;

    if (!accessToken) {
      return sendResponse({
        ok: false,
        error: "Você precisa estar logado para enviar uma avaliação.",
      });
    }

    const response = await fetch(`${apiUrl}/user/review`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${accessToken}`,
      },
      body: JSON.stringify({
        statusReview: "SUBMITTED",
        scoreReview: data.score,
        msgReview: data.message || null,
      }),
    });

    const result = await response.json();

    if (!response.ok) {
      throw new Error(result.message || "Erro ao enviar avaliação");
    }

    // Atualizar sessão local com os dados da avaliação
    await finalizeAndPersistSession(
      {
        statusReview: "SUBMITTED",
        scoreReview: data.score,
        msgReview: data.message || undefined,
      },
      "handleReviewSubmit",
    );

    sendResponse({ ok: true, ...result });
  } catch (error) {
    sendResponse({
      ok: false,
      error: (error as Error).message || "Ocorreu um erro. Tente novamente!",
    });
  }
}

