function normalizeEnvValue(value?: string): string | undefined {
  if (typeof value !== "string") return undefined;
  return value.trim().replace(/^"+|"+$/g, "");
}

function readEnv(key: string): string | undefined {
  let value: string | undefined;

  try {
    if (typeof process !== "undefined" && process?.env) {
      value = process.env[key];
    }
  } catch {
    // ignore when process is not available in MV3
  }

  if (value === undefined) {
    try {
      // @ts-expect-error import.meta may be undefined in some targets
      const metaEnv =
        typeof import.meta !== "undefined"
          ? (import.meta as any).env
          : undefined;
      if (metaEnv && key in metaEnv) {
        value = metaEnv[key];
      }
    } catch {
      // ignore when import.meta is not available
    }
  }

  return normalizeEnvValue(value);
}

function readEnvKey(key: "DEV" | "EMAIL"): string | undefined {
  let value: string | undefined;

  try {
    if (key === "DEV") {
      value = /* webpack.Define */ process.env.DEV;
    } else {
      value = /* webpack.Define */ process.env.EMAIL;
    }
  } catch {
    // ignore when process is not available in MV3
  }

  if (value === undefined) {
    try {
      // @ts-expect-error import.meta may be undefined in some targets
      const metaEnv =
        typeof import.meta !== "undefined"
          ? (import.meta as any).env
          : undefined;
      if (metaEnv) {
        value = key === "DEV" ? metaEnv.DEV : metaEnv.EMAIL;
      }
    } catch {
      // ignore when import.meta is not available
    }
  }

  return normalizeEnvValue(value);
}

const DEV_BYPASS_ENV = readEnvKey("DEV");
const DEV_EMAIL_HASH = normalizeEnvValue(readEnvKey("EMAIL"));
const cryptoRef =
  typeof globalThis !== "undefined" ? globalThis.crypto : undefined;

export const DEV_BYPASS_ENABLED = DEV_BYPASS_ENV === "true";

async function hashEmail(email: string): Promise<string> {
  const encoder = new TextEncoder();
  const normalizedEmail = email.trim().toLowerCase();
  const hashBuffer = await cryptoRef!.subtle.digest(
    "SHA-256",
    encoder.encode(normalizedEmail)
  );
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function isDevBypassAllowed(userEmail: string): Promise<boolean> {
  if (!DEV_BYPASS_ENABLED) return false;
  if (!DEV_EMAIL_HASH) return false;
  if (!cryptoRef?.subtle) return false;

  const hashed = await hashEmail(userEmail);
  return hashed === DEV_EMAIL_HASH.toLowerCase();
}

export function applyDevBypass(
  features: Record<string, boolean>
): Record<string, boolean> {
  if (!DEV_BYPASS_ENABLED) return features;

  const aliased = {
    ...features,
    EXTENSION: true,
    SAVER: true,
    MATURADOR: true,
  };

  return aliased;
}

export function getDevBypassDebugInfo() {
  return {
    enabled: DEV_BYPASS_ENABLED,
    hasEmailHash: Boolean(DEV_EMAIL_HASH),
  };
}
