import {
  collectWhatsAppEnvSnapshot,
  type WhatsAppEnvSnapshot,
} from "./whatsappEnv";
import { DEV_BYPASS_ENABLED } from "../../dev/devBypass";

export const ENV_REPORT_ENDPOINT = "/telemetry/environment";

type BrowserInfo = {
  name: string;
  versionFull: string;
};

type OsInfo = {
  name: string;
  platformVersion?: string;
};

type ArchInfo = {
  architecture: string;
  bitness: string;
};

type EnvironmentSnapshot = {
  timestamp: string;
  extensionVersion: string;
  sessionToken: string;
  browser: BrowserInfo;
  os: OsInfo;
  arch: ArchInfo;
  whatsapp: WhatsAppEnvSnapshot | null;
};

type NavigatorUADataLike = {
  platform?: string;
  brands?: Array<{ brand: string; version: string }>;
  getHighEntropyValues?: (
    hints: Array<
      | "fullVersionList"
      | "platform"
      | "platformVersion"
      | "architecture"
      | "bitness"
    >
  ) => Promise<{
    fullVersionList?: Array<{ brand: string; version: string }>;
    platform?: string;
    platformVersion?: string;
    architecture?: string;
    bitness?: string;
  }>;
};

const API_BASE_URL = process.env.API_URL;
const DEBUG_TELEMETRY = process.env.DEBUG_TELEMETRY === "true";

const LOCAL_TOKEN_KEY = "accessToken";
const SESSION_DEDUP_KEY = "telemetry.lastReportedForTokenHash";

let lastReportedForTokenHashMemory: string | null = null;
let initialized = false;

function debugLog(message: string, ...args: unknown[]) {
  if (DEV_BYPASS_ENABLED) {
    // Avoid logging token/email; only operational messages.
    console.log(message, ...args);
    return;
  }

  if (DEBUG_TELEMETRY) {
    console.log(message, ...args);
  }
}

async function sha256Hex(input: string): Promise<string> {
  const bytes = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  const hashArray = Array.from(new Uint8Array(digest));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

function normalizeOsName(
  os: chrome.runtime.PlatformOs | string | undefined
): string {
  switch (os) {
    case "win":
    case "windows":
      return "Windows";
    case "mac":
    case "macos":
      return "macOS";
    case "android":
      return "Android";
    case "cros":
      return "ChromeOS";
    case "linux":
      return "Linux";
    case "openbsd":
      return "OpenBSD";
    default:
      return typeof os === "string" && os.length ? os : "Unknown";
  }
}

function mapPlatformArchToSnapshot(
  platformArch: chrome.runtime.PlatformArch | undefined,
  uaArchitecture: string | undefined,
  uaBitness: string | undefined
): ArchInfo {
  let architecture = uaArchitecture || "";
  let bitness = uaBitness || "";

  if (!architecture || !bitness) {
    switch (platformArch) {
      case "x86-64":
        architecture = architecture || "x86_64";
        bitness = bitness || "64";
        break;
      case "x86-32":
        architecture = architecture || "x86";
        bitness = bitness || "32";
        break;
      case "arm":
        architecture = architecture || "arm";
        bitness = bitness || "unknown";
        break;
      case "arm64":
        architecture = architecture || "arm64";
        bitness = bitness || "64";
        break;
      case "mips":
        architecture = architecture || "mips";
        bitness = bitness || "unknown";
        break;
      case "mips64":
        architecture = architecture || "mips64";
        bitness = bitness || "64";
        break;
      default:
        break;
    }
  }

  return {
    architecture: architecture || "unknown",
    bitness: bitness || "unknown",
  };
}

function pickBrowser(
  fullVersionList?: Array<{ brand: string; version: string }>,
  brands?: Array<{ brand: string; version: string }>
): BrowserInfo {
  const list =
    fullVersionList && fullVersionList.length ? fullVersionList : brands || [];

  const preferred = list.find(
    (b) =>
      b.brand &&
      b.brand !== "Chromium" &&
      b.brand !== "Not.A/Brand" &&
      b.brand !== "Not;A=Brand"
  );

  const chosen = preferred || list[0];

  if (chosen?.brand && chosen?.version) {
    return { name: chosen.brand, versionFull: chosen.version };
  }

  // UA fallback
  const ua = navigator.userAgent || "";
  const edge = ua.match(/Edg\/([0-9.]+)/);
  if (edge) return { name: "Microsoft Edge", versionFull: edge[1] };
  const opera = ua.match(/OPR\/([0-9.]+)/);
  if (opera) return { name: "Opera", versionFull: opera[1] };
  const chromeMatch = ua.match(/Chrome\/([0-9.]+)/);
  if (chromeMatch) return { name: "Chrome", versionFull: chromeMatch[1] };
  const firefox = ua.match(/Firefox\/([0-9.]+)/);
  if (firefox) return { name: "Firefox", versionFull: firefox[1] };
  const safari = ua.match(/Version\/([0-9.]+).*Safari/);
  if (safari) return { name: "Safari", versionFull: safari[1] };

  return { name: "Unknown", versionFull: "" };
}

async function getBrowserOsArchSnapshot(): Promise<{
  browser: BrowserInfo;
  os: OsInfo;
  arch: ArchInfo;
}> {
  const uaData = (
    navigator as unknown as { userAgentData?: NavigatorUADataLike }
  ).userAgentData;

  let uaPlatform: string | undefined;
  let uaPlatformVersion: string | undefined;
  let uaArchitecture: string | undefined;
  let uaBitness: string | undefined;
  let fullVersionList: Array<{ brand: string; version: string }> | undefined;

  if (uaData?.getHighEntropyValues) {
    try {
      const values = await uaData.getHighEntropyValues([
        "fullVersionList",
        "platform",
        "platformVersion",
        "architecture",
        "bitness",
      ]);
      fullVersionList = values.fullVersionList;
      uaPlatform = values.platform;
      uaPlatformVersion = values.platformVersion;
      uaArchitecture = values.architecture;
      uaBitness = values.bitness;
    } catch {
      // ignore
    }
  } else {
    uaPlatform = uaData?.platform;
  }

  let platformInfo: chrome.runtime.PlatformInfo | null = null;
  try {
    platformInfo = await chrome.runtime.getPlatformInfo();
  } catch {
    platformInfo = null;
  }

  const browser = pickBrowser(fullVersionList, uaData?.brands);
  const osName = normalizeOsName(platformInfo?.os || uaPlatform);
  const os: OsInfo = {
    name: osName,
    ...(uaPlatformVersion ? { platformVersion: uaPlatformVersion } : {}),
  };

  const arch = mapPlatformArchToSnapshot(
    platformInfo?.arch,
    uaArchitecture,
    uaBitness
  );

  return { browser, os, arch };
}

async function getLastReportedHash(): Promise<string | null> {
  if (lastReportedForTokenHashMemory) return lastReportedForTokenHashMemory;

  try {
    const stored = await chrome.storage.session.get(SESSION_DEDUP_KEY);
    const value = stored?.[SESSION_DEDUP_KEY];
    if (typeof value === "string" && value.length) {
      lastReportedForTokenHashMemory = value;
      return value;
    }
  } catch {
    // ignore
  }

  return null;
}

async function setLastReportedHash(hash: string): Promise<void> {
  lastReportedForTokenHashMemory = hash;

  try {
    await chrome.storage.session.set({ [SESSION_DEDUP_KEY]: hash });
  } catch {
    // ignore
  }
}

async function postEnvironmentSnapshot(
  snapshot: EnvironmentSnapshot,
  token: string
): Promise<void> {
  if (!API_BASE_URL) return;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 8000);

  try {
    await fetch(`${API_BASE_URL}${ENV_REPORT_ENDPOINT}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(snapshot),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timeoutId);
  }
}

async function reportForToken(token: string): Promise<void> {
  const trimmed = token.trim();
  if (!trimmed) return;

  const tokenHash = await sha256Hex(trimmed);
  const lastHash = await getLastReportedHash();
  if (lastHash && lastHash === tokenHash) return;

  if (DEV_BYPASS_ENABLED) {
    console.log("[telemetry] reporting for token", { tokenHash });
  }

  // WhatsApp tab is assumed to exist. If not, fail silently and do not send.
  let whatsapp = await collectWhatsAppEnvSnapshot();
  if (!whatsapp) {
    // Small retry to avoid race with content script readiness.
    await new Promise((r) => setTimeout(r, 700));
    whatsapp = await collectWhatsAppEnvSnapshot();
  }

  if (!whatsapp) {
    if (DEV_BYPASS_ENABLED) {
      console.log("[telemetry] WhatsApp env not available; skipping", {
        tokenHash,
      });
    }

    debugLog("[telemetry] WhatsApp tab/env not available; skipping report");
    return;
  }

  const { browser, os, arch } = await getBrowserOsArchSnapshot();

  const snapshot: EnvironmentSnapshot = {
    timestamp: new Date().toISOString(),
    extensionVersion: chrome.runtime.getManifest().version,
    sessionToken: trimmed,
    browser,
    os,
    arch,
    whatsapp,
  };

  if (DEV_BYPASS_ENABLED) {
    console.log("[telemetry] environment snapshot", {
      timestamp: snapshot.timestamp,
      extensionVersion: snapshot.extensionVersion,
      browser: snapshot.browser,
      os: snapshot.os,
      arch: snapshot.arch,
      whatsapp: snapshot.whatsapp,
      sessionTokenHash: tokenHash,
    });
  }

  try {
    await postEnvironmentSnapshot(snapshot, trimmed);
    await setLastReportedHash(tokenHash);

    if (DEV_BYPASS_ENABLED) {
      console.log("[telemetry] report sent", {
        tokenHash,
        url: `${API_BASE_URL || ""}${ENV_REPORT_ENDPOINT}`,
      });
    }

    debugLog("[telemetry] report sent", {
      tokenHash,
      url: `${API_BASE_URL || ""}${ENV_REPORT_ENDPOINT}`,
    });
  } catch {
    // best-effort and silent
    if (DEV_BYPASS_ENABLED) {
      console.log("[telemetry] report failed (silent)", { tokenHash });
    }

    debugLog("[telemetry] report failed (silent)", { tokenHash });
  }
}

async function maybeReportFromStorageChange(
  changes: Record<string, chrome.storage.StorageChange>,
  areaName: string
): Promise<void> {
  if (areaName !== "local") return;

  const change = changes[LOCAL_TOKEN_KEY];
  if (!change) return;

  const oldValue = typeof change.oldValue === "string" ? change.oldValue : "";
  const newValue = typeof change.newValue === "string" ? change.newValue : "";

  // Trigger only on empty -> filled.
  if (oldValue.trim()) return;
  if (!newValue.trim()) return;

  if (DEV_BYPASS_ENABLED) {
    console.log("[telemetry] detected accessToken change empty->filled");
  }

  debugLog("[telemetry] detected accessToken change empty->filled");

  try {
    await reportForToken(newValue);
  } catch {
    // silent
  }
}

async function reportIfAlreadyLoggedIn(): Promise<void> {
  try {
    const res = await chrome.storage.local.get(LOCAL_TOKEN_KEY);
    const token = res?.[LOCAL_TOKEN_KEY];
    if (typeof token === "string" && token.trim()) {
      if (DEV_BYPASS_ENABLED) {
        console.log("[telemetry] accessToken already present on startup");
      }

      debugLog("[telemetry] accessToken already present on startup");
      await reportForToken(token);
    }
  } catch {
    // silent
  }
}

export function initEnvironmentReporter(): void {
  if (initialized) return;
  initialized = true;

  if (DEV_BYPASS_ENABLED) {
    console.log("[telemetry] initEnvironmentReporter", {
      hasApiBaseUrl: Boolean(API_BASE_URL),
      endpoint: ENV_REPORT_ENDPOINT,
    });
  }

  debugLog("[telemetry] initEnvironmentReporter", {
    hasApiBaseUrl: Boolean(API_BASE_URL),
    endpoint: ENV_REPORT_ENDPOINT,
  });

  try {
    chrome.storage.onChanged.addListener((changes, areaName) => {
      // Fire-and-forget; never block the SW.
      void maybeReportFromStorageChange(changes, areaName);
    });
  } catch {
    // ignore
  }

  // In case SW starts after login already happened.
  void reportIfAlreadyLoggedIn();
}
