export function toBase64(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();

    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export async function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

export function fromBase64ToFile(
  base64String: string,
  filename?: string
): File {
  // Valida se é uma data URL válida
  const dataUrlRegex = /^data:([^;]+);base64,/;
  const match = base64String.match(dataUrlRegex);

  if (!match) {
    throw new Error(
      "String base64 inválida. Deve ser uma data URL no formato 'data:mime/type;base64,...'"
    );
  }

  const mimeType = match[1];
  const base64Data = base64String.replace(dataUrlRegex, "");

  try {
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);

    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    let finalFilename = filename;
    if (!finalFilename) {
      const extension = getExtensionFromMimeType(mimeType);
      const timestamp = Date.now();
      finalFilename = `file_${timestamp}.${extension}`;
    }

    return new File([bytes], finalFilename, { type: mimeType });
  } catch (error) {
    throw new Error(
      `Erro ao converter base64 para arquivo: ${error instanceof Error ? error.message : "Erro desconhecido"}`
    );
  }
}

function getExtensionFromMimeType(mimeType: string): string {
  const mimeToExtension: Record<string, string> = {
    "audio/ogg": "ogg",
    "audio/mpeg": "mp3",
    "audio/wav": "wav",
    "audio/webm": "webm",
    "image/jpeg": "jpg",
    "image/png": "png",
    "image/gif": "gif",
    "image/webp": "webp",
    "video/mp4": "mp4",
    "video/webm": "webm",
    "application/pdf": "pdf",
    "text/plain": "txt",
    "application/json": "json",
    "application/zip": "zip",
  };

  return mimeToExtension[mimeType] || "bin";
}
